SELECT 'candle' AS src, interval_code, open_time AS t, CAST(closed AS CHAR) AS a, ingestion_source AS b, CAST(updated_at AS CHAR) AS c FROM candle WHERE symbol='XLMUSDT' AND ((interval_code='5m' AND open_time='2026-10-10 17:55:00') OR (interval_code='1h' AND open_time='2026-10-10 17:00:00')) UNION ALL SELECT 'outcome', interval_code, candle_open_time, outcome, CONCAT(reason_code,'/',origin), CAST(created_at AS CHAR) FROM candle_analysis_outcome WHERE symbol='XLMUSDT' AND ((interval_code='5m' AND candle_open_time='2026-10-10 17:55:00') OR (interval_code='1h' AND candle_open_time='2026-10-10 17:00:00')) UNION ALL SELECT 'audit', interval_code, candle_open_time, status, failure_reason, CAST(created_at AS CHAR) FROM local_reconciliation_audit WHERE symbol='XLMUSDT' AND interval_code IN ('5m','1h') AND candle_open_time IN ('2026-10-10 17:55:00','2026-10-10 17:00:00') LIMIT 50;